    public static int ptBrief(StringBuilder t, emon.Port.Cells nodes, emon.Port.Cells regions, emon.Port.Cells text) {
        // The brief of the Model (see the head of this file): every node but the root, in id order.
        int n = Model.nodeCount(nodes);
        int i = 1;
        int k = 0;
        int kind = 0;
        int s = 0;
        while (i < n) {
            kind = Model.nodeKind(nodes, i);
            if (kind == Model.nkParagraph()) {
                emon.Port.textCp(t, 80);
                emon.Port.textI32(t, Model.nodeRegionCount(nodes, i));
                emon.Port.textCp(t, 58);
            }
            if (kind == Model.nkText()) {
                emon.Port.textCp(t, 84);
                emon.Port.textCp(t, 58);
            }
            if (kind == Model.nkNote()) {
                emon.Port.textCp(t, 78);
                emon.Port.textI32(t, Model.nodeSub(nodes, i));
            }
            if (kind == Model.nkBreak()) {
                emon.Port.textCp(t, 66);
                emon.Port.textI32(t, Model.nodeSub(nodes, i));
            }
            if ((kind == Model.nkParagraph()) || (kind == Model.nkText())) {
                s = Model.nodeTextStart(nodes, i);
                k = 0;
                while (k < Model.nodeTextLen(nodes, i)) {
                    emon.Port.textCp(t, Model.textAt(text, s + k));
                    k += 1;
                }
            }
            emon.Port.textCp(t, 59);
            i += 1;
        }
        return 0;
    }
    public static void testAGapAndAnIndentEndAParagraph() {
        emon.Port.Cells wd = emon.Port.newCells();
        emon.Port.Cells ln = emon.Port.newCells();
        emon.Port.Cells et = emon.Port.newCells();
        emon.Port.Cells nodes = emon.Port.newCells();
        emon.Port.Cells attrs = emon.Port.newCells();
        emon.Port.Cells regions = emon.Port.newCells();
        emon.Port.Cells text = emon.Port.newCells();
        emon.Port.Cells pages = emon.Port.newCells();
        emon.Port.Cells ledger = emon.Port.newCells();
        emon.Port.Cells layout = emon.Port.newCells();
        emon.Port.Cells ord = emon.Port.newCells();
        emon.Port.Cells raw = emon.Port.newCells();
        emon.Port.Cells tmp = emon.Port.newCells();
        emon.Port.Cells fr = emon.Port.newCells();
        emon.Port.Cells gp = emon.Port.newCells();
        emon.Port.Cells st = emon.Port.newCells();
        StringBuilder t1 = emon.Testport.newText();
        StringBuilder t2 = emon.Testport.newText();
        StringBuilder t3 = emon.Testport.newText();
        StringBuilder t4 = emon.Testport.newText();
        // A vertical gap above 1.5 times the median: five lines, a tight run of three, a jump, two.
        ptLine(wd, ln, et, emon.Testport.textBlob("alpha beta"), 1, 7200, 10000, 50000, 11200, 0, 0, 1000);
        ptLine(wd, ln, et, emon.Testport.textBlob("gamma delta"), 1, 7200, 11500, 50000, 12700, 0, 0, 1000);
        ptLine(wd, ln, et, emon.Testport.textBlob("epsilon"), 1, 7200, 13000, 30000, 14200, 0, 0, 1000);
        ptLine(wd, ln, et, emon.Testport.textBlob("zeta eta"), 1, 7200, 15400, 50000, 16600, 0, 0, 1000);
        ptLine(wd, ln, et, emon.Testport.textBlob("theta"), 1, 7200, 16900, 20000, 18100, 0, 0, 1000);
        emon.Testport.assertEq(ptRun(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "gap: well formed");
        ptBrief(t1, nodes, regions, text);
        emon.Testport.assertText(t1, "P1:alpha beta gamma delta epsilon;P1:zeta eta theta;", "a gap of 12 pt after lines 3 pt apart starts a paragraph");
        // An indent: more than half the size, from a line at the margin. The first line of a paragraph is
        // indented, the rest are not: a LESS indented line goes on (a hanging or ordinary paragraph).
        ptClear(wd, ln, et);
        ptLine(wd, ln, et, emon.Testport.textBlob("one two"), 1, 9600, 10000, 50000, 11200, 0, 0, 1000);
        ptLine(wd, ln, et, emon.Testport.textBlob("three four"), 1, 7200, 11500, 50000, 12700, 0, 0, 1000);
        ptLine(wd, ln, et, emon.Testport.textBlob("five"), 1, 7200, 13000, 30000, 14200, 0, 0, 1000);
        ptLine(wd, ln, et, emon.Testport.textBlob("six seven"), 1, 9600, 14500, 50000, 15700, 0, 0, 1000);
        ptLine(wd, ln, et, emon.Testport.textBlob("eight"), 1, 7200, 16000, 20000, 17200, 0, 0, 1000);
        emon.Testport.assertEq(ptRun(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "indent: well formed");
        ptBrief(t2, nodes, regions, text);
        emon.Testport.assertText(t2, "P1:one two three four five;P1:six seven eight;", "an indented line after one at the margin starts a paragraph");
        // Centred lines start anywhere: a line that does not start at the page's margin is not an indent. The
        // first line is at the margin (and ends the first paragraph with its gap), the three centred lines go on.
        ptClear(wd, ln, et);
        ptLine(wd, ln, et, emon.Testport.textBlob("left"), 1, 7200, 10000, 20000, 11200, 0, 0, 1000);
        ptLine(wd, ln, et, emon.Testport.textBlob("mid a"), 1, 9000, 13000, 40000, 14200, 0, 0, 1000);
        ptLine(wd, ln, et, emon.Testport.textBlob("mid bb"), 1, 11000, 14500, 38000, 15700, 0, 0, 1000);
        ptLine(wd, ln, et, emon.Testport.textBlob("mid c"), 1, 10000, 16000, 39000, 17200, 0, 0, 1000);
        emon.Testport.assertEq(ptRun(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "centred: well formed");
        ptBrief(t3, nodes, regions, text);
        emon.Testport.assertText(t3, "P1:left;P1:mid a mid bb mid c;", "centred lines are one paragraph");
        // Lines on one row (two columns, a table row) do not follow one another: the second is not below the first.
        ptClear(wd, ln, et);
        ptLine(wd, ln, et, emon.Testport.textBlob("left col"), 1, 7200, 10000, 25000, 11200, 0, 0, 1000);
        ptLine(wd, ln, et, emon.Testport.textBlob("right col"), 1, 30000, 10000, 50000, 11200, 0, 0, 1000);
        emon.Testport.assertEq(ptRun(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "row: well formed");
        ptBrief(t4, nodes, regions, text);
        emon.Testport.assertText(t4, "P1:left col;P1:right col;", "two lines on one row are two paragraphs");
    }
    public static void testLinesAreReadTopToBottomWhateverOrderTheyWerePainted() {
        emon.Port.Cells wd = emon.Port.newCells();
        emon.Port.Cells ln = emon.Port.newCells();
        emon.Port.Cells et = emon.Port.newCells();
        emon.Port.Cells nodes = emon.Port.newCells();
        emon.Port.Cells attrs = emon.Port.newCells();
        emon.Port.Cells regions = emon.Port.newCells();
        emon.Port.Cells text = emon.Port.newCells();
        emon.Port.Cells pages = emon.Port.newCells();
        emon.Port.Cells ledger = emon.Port.newCells();
        emon.Port.Cells layout = emon.Port.newCells();
        emon.Port.Cells ord = emon.Port.newCells();
        emon.Port.Cells raw = emon.Port.newCells();
        emon.Port.Cells tmp = emon.Port.newCells();
        emon.Port.Cells fr = emon.Port.newCells();
        emon.Port.Cells gp = emon.Port.newCells();
        emon.Port.Cells st = emon.Port.newCells();
        StringBuilder t1 = emon.Testport.newText();
        StringBuilder t2 = emon.Testport.newText();
        // Painted last line first and the first line in the middle (a float is painted before the page's text).
        ptLine(wd, ln, et, emon.Testport.textBlob("three"), 1, 7200, 13000, 30000, 14200, 0, 0, 1000);
        ptLine(wd, ln, et, emon.Testport.textBlob("one"), 1, 7200, 10000, 30000, 11200, 0, 0, 1000);
        ptLine(wd, ln, et, emon.Testport.textBlob("two"), 1, 7200, 11500, 30000, 12700, 0, 0, 1000);
        emon.Testport.assertEq(ptRun(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "order: well formed");
        ptBrief(t1, nodes, regions, text);
        emon.Testport.assertText(t1, "P1:one two three;", "the reading order is the page's, not the painting's");
        // A rotated line is not in the column of upright ones: it stands alone, after them (a watermark
        // across the middle of a paragraph does not cut it), and does not stop the paragraph that goes on.
        ptClear(wd, ln, et);
        ptLine(wd, ln, et, emon.Testport.textBlob("first line"), 1, 7200, 10000, 50000, 11200, 0, 0, 1000);
        ptLine(wd, ln, et, emon.Testport.textBlob("DRAFT"), 1, 20000, 11000, 30000, 12500, 4500, 0, 3000);
        ptLine(wd, ln, et, emon.Testport.textBlob("second line"), 1, 7200, 11500, 50000, 12700, 0, 0, 1000);
        emon.Testport.assertEq(ptRun(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "rotated: well formed");
        ptBrief(t2, nodes, regions, text);
        emon.Testport.assertText(t2, "P1:first line second line;P1:DRAFT;", "a rotated line stands alone, after the upright ones");
    }
