    public static int ptGolden(byte[] pdf, StringBuilder t, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells ox, emon.Port.Cells cs, emon.Port.Cells out, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells mk, emon.Port.Cells fnt, emon.Port.Cells pg, emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells pages, emon.Port.Cells ledger, emon.Port.Cells layout, emon.Port.Cells ord, emon.Port.Cells raw, emon.Port.Cells tmp, emon.Port.Cells fr, emon.Port.Cells gp, emon.Port.Cells mst) {
        // PDF -> content -> paragraphs -> Model -> pretty JSON; answer 0 when every step answered 0, else a
        // code naming the step (1 open, 2 content, 3 the Model's check). The JSON is `t`.
        emon.Port.cellsDrop(gl, 0);
        emon.Port.cellsDrop(et, 0);
        emon.Port.cellsDrop(mk, 0);
        emon.Port.cellsDrop(fnt, 0);
        emon.Port.cellsDrop(wd, 0);
        emon.Port.cellsDrop(ln, 0);
        emon.Port.Src src = emon.Port.srcOfBlob(pdf);
        emon.Port.Cells pa = emon.Port.newCells();
        emon.Port.Cells im = emon.Port.newCells();
        emon.Port.Cells pts = emon.Port.newCells();
        emon.Port.Cells gx = emon.Port.newCells();
        int o = Pdfdoc.pdOpen(src, ar, dc, a, b, st);
        if (o != 0) {
            return 1;
        }
        if (Pdfcontent.pcDocument(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln, pa, im, pts, gx) != 0) {
            return 2;
        }
        Model.modelInit(nodes, attrs, regions, text, pages, ledger, layout);
        Para.paPages(pg, pages);
        int np = emon.Port.cellsLen(pages) / 16;
        emon.Port.Cells sf = emon.Port.newCells();
        emon.Port.Cells sc = emon.Port.newCells();
        emon.Port.Cells hc = emon.Port.newCells();
        emon.Port.Cells ws = emon.Port.newCells();
        emon.Port.Cells htmp = emon.Port.newCells();
        emon.Port.Cells hpr = emon.Port.newCells();
        emon.Port.Cells hptxt = emon.Port.newCells();
        emon.Port.Cells lt = emon.Port.newCells();
        emon.Port.Cells ii = emon.Port.newCells();
        ptPrep(wd, ln, et, np, gl, fnt, lt, ii);
        Heading.hdAnalyze(wd, lt, et, gl, sf, sc, hc, ws, htmp, hpr, hptxt);
        ptBuild(wd, et, np, pages, layout, nodes, attrs, regions, text, ord, raw, tmp, fr, gp, hc, lt, ii);
        if (Model.modelCheck(nodes, attrs, regions, text, pages, ledger, layout, mst) != 0) {
            return 3;
        }
        Json.jsEmit(t, 1, nodes, attrs, regions, text, pages, ledger, layout, layout, layout);
        return 0;
    }
